'use strict';
(function(root){
 const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function matches(c,key){if(key==='all')return true;const [product,pathway]=key.split('::');return c.product===product&&(!pathway||c.pathway===pathway)}
 function options(programmes,selected='all'){
  return '<option value="all">All products & programme contexts</option>'+programmes.map(p=>`<option value="${escape(p.product)}" ${selected===p.product?'selected':''}>${escape(p.product)}${p.kind==='Operational context'?' — operational context':''}</option>`).join('')+'<optgroup label="Motor finance pathways">'+['Commission & disclosure','Vehicle quality & warranty'].map(p=>`<option value="${escape('Motor Finance::'+p)}" ${selected==='Motor Finance::'+p?'selected':''}>Motor Finance · ${escape(p)}</option>`).join('')+'</optgroup>';
 }
 function profile(data,key){const [product,pathway]=key.split('::');const p=data.programmes.find(p=>p.product===product);if(!p)return null;const result={...p,pathway};if(pathway==='Commission & disclosure'){result.summary='Commission and disclosure complaints, with agreement and dealer/broker evidence tracked separately from vehicle-quality disputes.';result.evidence=p.evidence.slice(0,2);result.control='Use an authorised reviewer to establish the applicable rules and evidence. This prototype applies no scheme eligibility, complaint-handling deadlines or commission-redress formula.'}if(pathway==='Vehicle quality & warranty'){result.summary='Reported braking, engine and gearbox concerns, repeated repairs, rejection requests and disputed warranty exclusions.';result.evidence=[p.evidence[0],...p.evidence.slice(2)];result.control='Escalate reported safety concerns under the agreed procedure. Technical evidence, warranty terms and the relevant agreement require qualified review; no mechanical fault or liability is decided by this dashboard.'}return result}
 function render(data,key,active,onCases){
  const container=document.querySelector('#programme-detail');if(!container)return;
  const p=profile(data,key);
  const total=active.metrics.total.toLocaleString('en-GB');
  const progress=Object.fromEntries((active.readiness||[]).map(x=>[x.status,x.volume]));
  const exceptions=active.complaint_types.reduce((a,c)=>({evidence:a.evidence+c.evidence_gaps,specialist:a.specialist+c.specialist_pending,safety:a.safety+c.safety_flags}),{evidence:0,specialist:0,safety:0});
  document.querySelector('#active-scope-note').textContent=`Viewing: ${key==='all'?'all products and contexts':key.replace('::',' · ')} · ${total} synthetic cases. Metrics, process, 3D network, risks, trends, brief and scenario baseline below use this population.`;
  const summary=p?p.summary:'I use the same case-management, process-mapping and analytical controls across different products and programmes. Choose a context to explore the relevant complaints, evidence and review points.';
  const types=active.complaint_types;
  container.innerHTML=`<div class="programme-description"><div class="eyebrow">${p?escape(p.kind+(p.pathway?' / '+p.pathway:'')):'TRANSFERABLE EXPERIENCE / SIX AREAS'}</div><h3>${p?escape(p.pathway||p.product):'One operational approach. Multiple situations.'}</h3><p>${escape(summary)}</p><div class="programme-counters"><div><strong>${exceptions.evidence.toLocaleString('en-GB')}</strong><span>incomplete-evidence cases</span></div><div><strong>${exceptions.specialist.toLocaleString('en-GB')}</strong><span>awaiting specialist review</span></div><div><strong>${exceptions.safety.toLocaleString('en-GB')}</strong><span>reported vehicle-safety concerns</span></div></div><div class="progress-counts scope-progress"><div><strong>${(progress['Open — waiting for evidence or review']||0).toLocaleString('en-GB')}</strong><span>Open — waiting for evidence or review</span></div><div><strong>${(progress['Open — ready for the next action']||0).toLocaleString('en-GB')}</strong><span>Open — ready for the next action</span></div><div><strong>${(progress.Closed||0).toLocaleString('en-GB')}</strong><span>Closed cases</span></div></div><p class="footnote">Case progress is separate from passing data checks. Ready means the example checks for the current stage pass; a person still authorises the next action. Intake may be ready for triage while later investigation evidence is outstanding.</p><p class="footnote">Operational flags from synthetic cases, not findings of unsuitable advice, mechanical fault, liability or regulatory eligibility. Safety flags include open and closed case histories.</p><a id="scope-respond-link" class="evidence-link" href="respond-integration.html?scope=${encodeURIComponent(key)}">Follow this context through the Respond integration ↗</a></div><div class="programme-evidence"><div class="eyebrow">${p?'RELEVANT EVIDENCE & HUMAN CONTROL':'PRODUCT & PROGRAMME COVERAGE'}</div>${p?`<ul>${p.evidence.map(e=>`<li>${escape(e)}</li>`).join('')}</ul><p>${escape(p.control)}</p>`:`<div class="coverage-list">${data.programmes.map(p=>`<span>${escape(p.product)}<small>${escape(p.kind)}</small></span>`).join('')}</div><p>Collections & recoveries is an operational context. Each case belongs to one synthetic population, so the totals reconcile without double-counting.</p>`}<details><summary>Complaint types in this population (${types.length})</summary><div class="complaint-type-list">${types.map(t=>`<button data-type="${escape(t.complaint_type)}">${escape(t.complaint_type)} <b>${t.volume.toLocaleString('en-GB')}</b></button>`).join('')}</div></details></div>`;
  if(p?.product==='Motor Finance'){container.querySelector('.programme-evidence').insertAdjacentHTML('beforeend','<p class="product-references">Reference material: <a href="https://www.financial-ombudsman.org.uk/businesses/resolving-complaint/complaints-deal/consumer-credit/car-finance" target="_blank" rel="noopener">FOS car-finance complaints</a> · <a href="https://www.financial-ombudsman.org.uk/consumers/complaints-can-help/insurance/extended-warranties" target="_blank" rel="noopener">FOS extended warranties</a> · <a href="https://www.fca.org.uk/firms/information-firms-motor-finance-complaints" target="_blank" rel="noopener">FCA commission complaint information</a>. This prototype does not implement scheme rules or determine complaint jurisdiction.</p>')}
  container.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>onCases(b.dataset.type));
 }
 function stageContext(data,key,stage){const p=profile(data,key);if(!p)return 'Product-specific evidence and approval controls are available in the programme selector.';if(stage==='Evidence')return 'Evidence focus: '+p.evidence.join('; ')+'.';if(['Investigation','Decision','Redress'].includes(stage))return p.control;return 'Follow the agreed '+p.product.toLowerCase()+' complaint process, retain the source reference and record human approval where required.'}
 root.ProgrammeExplorer={matches,options,profile,render,stageContext};
 if(typeof module!=='undefined')module.exports=root.ProgrammeExplorer;
})(typeof globalThis!=='undefined'?globalThis:this);

